export const PHOTO_PATHS = {
  portrait: "/assets/adwokat.webp",
  square:   "/assets/adwokat-og.webp",
  logo:     "/assets/logo.webp",
  wnetrze:  "/assets/wnetrze.webp",
};

export const PHOTO_DIMS = {
  portrait: { w: 560, h: 747 },
  square:   { w: 1000, h: 1000 },
  logo:     { w: 554, h: 130 },
  wnetrze:  { w: 1600, h: 1062 },
};

/** Zwraca obraz albo null, gdy sciezka nie nalezy do zasobow zdjeciowych. */
export function photoResponse(pathname) {
  const b64 = pathname === PHOTO_PATHS.portrait ? PORTRAIT_B64
            : pathname === PHOTO_PATHS.square   ? SQUARE_B64
            : pathname === PHOTO_PATHS.logo     ? LOGO_B64
            : pathname === PHOTO_PATHS.wnetrze  ? WNETRZE_B64
            : null;
  if (!b64) return null;
  return new Response(decode(b64), {
    headers: {
      "Content-Type": "image/webp",
      "Cache-Control": "public, max-age=31536000, immutable",
    },
  });
}
